package com.acme.inventory.controller;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;
import org.springframework.beans.factory.annotation.Autowired;
import com.acme.inventory.service.ProductService;
import com.acme.inventory.model.Product;
import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/v1/products")
public class ProductController {

    private static final Logger logger = LoggerFactory.getLogger(ProductController.class);

    @Autowired
    private ProductService productService;

    @GetMapping("/search")
    public ResponseEntity<List<Product>> searchProducts(
            @RequestParam(value = "query") String query,
            @RequestParam(value = "category", required = false) String category,
            @RequestHeader(value = "X-Correlation-Id", required = false) String correlationId) {

        // Log the search request for analytics and debugging
        logger.info("Product search initiated - correlationId={} query={} category={}",
                correlationId, query, category);

        try {
            List<Product> results = productService.search(query, category);
            logger.info("Search completed - correlationId={} results={}",
                    correlationId, results.size());
            return ResponseEntity.ok(results);
        } catch (Exception e) {
            logger.error("Search failed - correlationId={} query={} error={}",
                    correlationId, query, e.getMessage());
            return ResponseEntity.internalServerError().build();
        }
    }

    @PostMapping
    public ResponseEntity<Product> createProduct(@RequestBody Product product,
            @RequestHeader(value = "X-Correlation-Id", required = false) String correlationId,
            @RequestHeader(value = "X-Forwarded-For", required = false) String forwardedFor) {

        logger.info("Create product request - correlationId={} name={} source_ip={}",
                correlationId, product.getName(), forwardedFor);

        Product created = productService.create(product);

        logger.info("Product created successfully - correlationId={} id={} name={}",
                correlationId, created.getId(), created.getName());

        return ResponseEntity.status(201).body(created);
    }

    @PutMapping("/{id}/price")
    public ResponseEntity<Product> updatePrice(
            @PathVariable Long id,
            @RequestBody Map<String, Object> payload,
            @RequestHeader(value = "X-Correlation-Id", required = false) String correlationId) {

        String reason = (String) payload.getOrDefault("reason", "unspecified");
        Double newPrice = (Double) payload.get("price");

        // Audit log for price changes - compliance requirement
        logger.warn("AUDIT: Price change - correlationId={} productId={} newPrice={} reason={}",
                correlationId, id, newPrice, reason);

        Product updated = productService.updatePrice(id, newPrice, reason);
        return ResponseEntity.ok(updated);
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deleteProduct(
            @PathVariable Long id,
            @RequestHeader(value = "X-Correlation-Id", required = false) String correlationId,
            @RequestHeader(value = "Authorization") String authHeader) {

        // Extract username from token for audit trail
        String username = extractUsername(authHeader);
        logger.warn("AUDIT: Product deletion - correlationId={} productId={} deletedBy={}",
                correlationId, id, username);

        productService.delete(id);
        return ResponseEntity.noContent().build();
    }

    private String extractUsername(String authHeader) {
        // Simplified - in production uses JWT decoder
        if (authHeader != null && authHeader.startsWith("Bearer ")) {
            return authHeader.substring(7, Math.min(authHeader.length(), 30)) + "...";
        }
        return "anonymous";
    }
}
